CREATE TABLE work_orders(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,assignee_id BIGINT,category VARCHAR(32),location VARCHAR(255),description VARCHAR(1024),urgency VARCHAR(16),status VARCHAR(32),images_json VARCHAR(4000),source_type VARCHAR(16),version INT DEFAULT 0,created_by BIGINT,updated_by BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE work_order_events(id BIGINT PRIMARY KEY,work_order_id BIGINT,from_status VARCHAR(32),to_status VARCHAR(32),operator_id BIGINT,comment VARCHAR(512),created_at TIMESTAMP);
CREATE TABLE work_order_ratings(id BIGINT PRIMARY KEY,work_order_id BIGINT,user_id BIGINT,score INT,comment VARCHAR(512),created_at TIMESTAMP,UNIQUE(work_order_id,user_id));
CREATE TABLE campus_issues(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,title VARCHAR(256),category VARCHAR(32),description VARCHAR(1024),status VARCHAR(32),follow_count INT DEFAULT 0,vote_count INT DEFAULT 0,source_type VARCHAR(16),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP,visibility VARCHAR(16) DEFAULT 'private');
CREATE TABLE campus_issue_locations(id BIGINT PRIMARY KEY,issue_id BIGINT,name VARCHAR(128),latitude DECIMAL(10,7),longitude DECIMAL(10,7),created_at TIMESTAMP);
CREATE TABLE campus_issue_follows(id BIGINT PRIMARY KEY,issue_id BIGINT,user_id BIGINT,created_at TIMESTAMP,UNIQUE(issue_id,user_id));
CREATE TABLE campus_issue_evidences(id BIGINT PRIMARY KEY,issue_id BIGINT,user_id BIGINT,content VARCHAR(512),images_json VARCHAR(4000),created_at TIMESTAMP);
CREATE TABLE campus_issue_votes(id BIGINT PRIMARY KEY,issue_id BIGINT,user_id BIGINT,value INT,created_at TIMESTAMP,UNIQUE(issue_id,user_id));
CREATE TABLE resources(id BIGINT PRIMARY KEY,campus_id BIGINT,region_id BIGINT,type VARCHAR(32),name VARCHAR(128),capacity INT,equipment_json VARCHAR(4000),status VARCHAR(32),source_type VARCHAR(16),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE resource_slots(id BIGINT PRIMARY KEY,resource_id BIGINT,slot_date DATE,start_time TIME,end_time TIME,capacity INT,status VARCHAR(32),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE reservations(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,slot_id BIGINT,seat_no INT DEFAULT 0,status VARCHAR(32),source_type VARCHAR(16),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE resource_occupancies(id BIGINT PRIMARY KEY,slot_id BIGINT,reservation_id BIGINT,seat_no INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(slot_id,seat_no),UNIQUE(reservation_id));
CREATE TABLE reservation_checkins(id BIGINT PRIMARY KEY,reservation_id BIGINT,checked_in_at TIMESTAMP,created_at TIMESTAMP,UNIQUE(reservation_id));
CREATE TABLE crowd_observations(id BIGINT PRIMARY KEY,campus_id BIGINT,location_type VARCHAR(32),location_name VARCHAR(128),crowd_level VARCHAR(16),source_type VARCHAR(16),observed_at TIMESTAMP,is_stale BOOLEAN DEFAULT FALSE,created_at TIMESTAMP);
